    '{"client":{"name":"Camila Albuquerque","occupation":"Sócia Fundadora & CTO","summary":"Camila descobriu que seu sócio administrador transferiu secretamente as marcas, patentes de software e o faturamento principal da empresa para uma holding paralela criada em nome da cunhada.","avatarBg":"bg-emerald-100 text-emerald-900 border-emerald-300"},"briefing":{"mentorName":"Dr. Roberto Ramos","mentorQuote":"Caso clássico de quebra do dever de lealdade societária e desvio de clientela! Como Estagiário Sênior, você deve coletar a certidão de inteiro teor na Junta Comercial (JUCESP), a ata notarial do código-fonte e os extratos fiscais para embasar a exclusão do sócio desleal e bloqueio de bens.","facts":["A empresa foi avaliada em R$ 2,5 milhões em rodada seed.","O sócio alterou os acessos aos repositórios e contas da empresa.","Uma empresa clone com nome idêntico foi aberta na mesma semana.","Temos 56 horas antes da transferência internacional do faturamento."],"mainObjective":"Comprovar a confusão patrimonial, o desvio de finalidade societária e obter a tutela cautelar de arresto de bens e afastamento do administrador.","legalContext":"Desconsideração da personalidade jurídica (art. 50 do Código Civil) e exclusão judicial de sócio por falta grave."},"locations":[{"id":"LOC_ESCRITORIO_RAMOS_3","name":"Escritório Ramos & Associados","category":"escritorio","travelTimeHours":0,"travelCost":0,"description":"Sala de reuniões corporativas.","address":"Av. Paulista, 1200 - Conjunto 804","iconName":"Building2","color":"text-amber-500","unlockedByDefault":true,"characters":[{"id":"CHAR_DR_ROBERTO_3","name":"Dr. Roberto Ramos","role":"Sócio Fundador","avatarIcon":"Briefcase","avatarBg":"bg-slate-800 text-amber-400 border-amber-500","initialDialogue":"Na Junta Comercial você encontrará o contrato social original e as alterações fraudulentas não assinadas pela Camila.","dialogueOptions":[{"id":"diag_roberto_sociedade","question":"Como comprovar a fraude na Junta Comercial?","answer":"A certidão simplificada e a ficha cadastral completa mostrarão o endereço cruzado da empresa clone e os sócios laranjas!","timeCostMinutes":20}]}],"searchables":[{"id":"spot_lei_sociedades","name":"Tratado de Direito Comercial e Falimentar","description":"Pesquisar art. 1.030 do Código Civil sobre exclusão de sócio.","timeCostMinutes":25,"foundClueId":"CLUE_DOUTRINA_EXCLUSAO_SOCIO","inspectedMessage":"O art. 1.030 do CC autoriza a exclusão judicial do sócio por justa causa diante do cometimento de falta grave no cumprimento de suas obrigações."}]},{"id":"LOC_SEDE_NEXATECH","name":"Sede da Startup NexaTech (Vila Olímpia)","category":"empresa","travelTimeHours":3,"travelCost":50,"description":"Escritório moderno em espaço de coworking de alto padrão.","address":"Rua Funchal, 418 - 14º andar","iconName":"Briefcase","color":"text-emerald-400","unlockedByDefault":true,"characters":[{"id":"CHAR_CAMILA_CTO","name":"Camila Albuquerque","role":"Cliente & CTO","avatarIcon":"User","avatarBg":"bg-emerald-100 text-emerald-900 border-emerald-300","initialDialogue":"Meu sócio Rodrigo bloqueou meu login de administradora na AWS e nos bancos. Descobri que os contratos de clientes foram todos reemitidos com o CNPJ da empresa Nexa Global!","dialogueOptions":[{"id":"diag_camila_ata_notarial","question":"Você conseguiu fazer ata notarial do desvio dos clientes e mensagens?","answer":"Sim! Fui ao cartório e registrei a ata notarial de todas as conversas do Slack e WhatsApp onde ele confessa a manobra!","revealsClueId":"CLUE_ATA_NOTARIAL_MENSAGENS","timeCostMinutes":30}]}],"searchables":[{"id":"spot_servidor_logs","name":"Servidor Local e Backup de E-mails","description":"Recolher os e-mails com as ordens de pagamento direcionadas à conta paralela.","timeCostMinutes":45,"foundClueId":"CLUE_EMAILS_DESVIO_FATURAMENTO","inspectedMessage":"E-mails comprovando a ordem do sócio para que clientes de grande porte fizessem PIX para a empresa espelho da cunhada."}]},{"id":"LOC_JUNTA_COMERCIAL"