    '{"client":{"name":"Lucas Ferreira","occupation":"Professor, 34 anos","summary":"Após a morte do pai, Lucas descobriu que o inventário foi aberto sem seu nome e que um apartamento relevante está prestes a ser vendido pelos demais herdeiros.","avatarBg":"bg-indigo-950 text-indigo-200 border-indigo-500"},"briefing":{"mentorName":"Dr. Roberto Ramos","mentorQuote":"Agora você assina a estratégia. Proteja o patrimônio antes de discutir quem está moralmente certo.","facts":["Lucas possui certidão de nascimento com filiação reconhecida.","O inventário extrajudicial foi iniciado por dois irmãos.","Há minuta de venda de um apartamento pertencente ao espólio.","A escritura pode ser assinada em poucos dias."],"mainObjective":"Reconhecer a participação sucessória de Lucas e impedir a alienação do patrimônio antes da partilha correta.","legalContext":"Vocação hereditária, petição de herança, inventário, reserva de quinhão e tutela de urgência."},"locations":[{"id":"C05_ESCRITORIO","name":"Ramos & Associados — Família","category":"escritorio","travelTimeHours":0,"travelCost":0,"description":"Sala de análise patrimonial e sucessória.","address":"Av. Paulista, 1200","iconName":"Building2","color":"text-amber-500","unlockedByDefault":true,"characters":[{"id":"C05_MENTOR","name":"Dr. Roberto Ramos","role":"Sócio","avatarIcon":"Briefcase","avatarBg":"bg-slate-800 text-amber-300 border-amber-500","initialDialogue":"O risco aqui é o patrimônio sair do espólio.","dialogueOptions":[{"id":"C05_D_PRIORIDADE","question":"Qual é a primeira prioridade?","answer":"Assegurar o bem e demonstrar a qualidade de herdeiro. Depois discutimos a partilha.","timeCostMinutes":15}]}],"searchables":[{"id":"C05_S_CERTIDAO","name":"Documentos de filiação","description":"Conferir certidões e reconhecimento de paternidade.","timeCostMinutes":25,"foundClueId":"C05_CLUE_FILIACAO","inspectedMessage":"A certidão atualizada demonstra filiação sem qualquer ressalva."}]},{"id":"C05_CARTORIO","name":"8º Tabelionato