    '{"client":{"name":"André Luiz Santos","occupation":"Entregador, 26 anos","summary":"André foi preso preventivamente após reconhecimento fotográfico feito por uma única vítima. Ele afirma que estava trabalhando em outro bairro no horário do roubo.","avatarBg":"bg-red-950 text-red-200 border-red-500"},"briefing":{"mentorName":"Dra. Camila Torres (Criminalista)","mentorQuote":"Liberdade exige velocidade, mas velocidade não autoriza descuido. Verifique o reconhecimento, o álibi e a cadeia da prova antes de pedir soltura.","facts":["A prisão se baseia principalmente em reconhecimento por fotografia.","Não houve apreensão de objetos do crime com André.","O aplicativo de entregas registra rota no horário do roubo.","A audiência de custódia já ocorreu e a preventiva foi mantida."],"mainObjective":"Demonstrar a fragilidade do reconhecimento e construir álibi verificável para buscar a revogação da prisão.","legalContext":"Reconhecimento pessoal, prova penal, presunção de inocência, prisão preventiva e habeas corpus."},"locations":[{"id":"C06_ESCRITORIO","name":"Núcleo Criminal do Escritório","category":"escritorio","travelTimeHours":0,"travelCost":0,"description":"Sala reservada para análise de autos criminais.","address":"Av. Paulista, 1200","iconName":"Building2","color":"text-amber-500","unlockedByDefault":true,"characters":[{"id":"C06_CAMILA","name":"Dra. Camila Torres","role":"Advogada Criminalista","avatarIcon":"Briefcase","avatarBg":"bg-slate-800 text-red-300 border-red-500","initialDialogue":"Leia o auto de reconhecimento palavra por palavra.","dialogueOptions":[{"id":"C06_D_RECON","question":"O reconhecimento fotográfico basta?","answer":"Ele precisa ser analisado com muita cautela e em conjunto com outras provas. Procedimento sugestivo contamina a confiabilidade.","timeCostMinutes":15}]}],"searchables":[{"id":"C06_S_AUTOS","name":"Auto de reconhecimento","description":"Verificar como as fotos foram apresentadas.","timeCostMinutes":35,"foundClueId":"C06_CLUE_RECON_SUGESTIVO","inspectedMessage":"A vítima recebeu uma única fotografia de André acompanhada da pergunta: “foi este homem?”."}]},{"id":"C06_DELEGACIA","name":"5º Distrito Policial","category":"delegacia","travelTimeHours":2,"travelCost":28,"description":"Delegacia responsável pelo inquérito.","address":"Zona Norte - São Paulo","iconName":"ShieldAlert","color":"text-red-400","unlockedByDefault":true,"characters":[{"id":"C06_INVESTIGADOR","name":"Paulo Esteves","role":"Investigador","avatarIcon":"Badge","avatarBg":"bg-red-950 text-red-200 border-red-500","initialDialogue":"Recebemos uma denúncia anônima e mostramos a foto.","dialogueOptions":[{"id":"C06_D_DENUNCIA","question":"A denúncia anônima trouxe algum dado verificável?","answer":"Só dizia o primeiro nome e descrevia uma moto preta. Não houve placa nem endereço.","revealsClueId":"C06_CLUE_DENUNCIA_FRACA","timeCostMinutes":20},{"id":"C06_D_APREENSAO","question":"Algum bem da vítima foi encontrado com André?","answer":"Não. Também não localizamos arma ou a roupa descrita.","revealsClueId":"C06_CLUE_SEM_APREENSAO","timeCostMinutes":15}]}],"searchables":[{"id":"C06_S_CAMERA","name":"Mídia anexada ao inquérito","description":"Examinar vídeo do local do crime.","timeCostMinutes":45,"foundClueId":"C06_CLUE_VIDEO","inspectedMessage":"A gravação é distante, mas indica altura e jaqueta diferentes das de André."}]},{"id":"C06_EMPRESA_APP","name":"Central do Aplicativo de Entregas","category":"empresa","travelTimeHours":2,"travelCost":32,"description":"Escritório regional da plataforma onde André trabalhava.","address":"Pinheiros - São Paulo","iconName":"Laptop","color":"text-blue-400","unlockedByDefault":true,"characters":[{"id":"C06_ANALISTA","name":"Natália Prado","role":"Analista de Operações","avatarIcon":"User","avatarBg":"bg-blue-950 text-blue-200 border-blue-500","initialDialogue":"Temos geolocalização vinculada às entregas aceitas.","dialogueOptions":[{"id":"C06_D_ROTA","question":"É possível certificar a rota daqu