    '{"client":{"name":"Café Horizonte Ltda.","occupation":"Cafeteria com 14 funcionários","summary":"Após anos no mesmo ponto, a cafeteria recebeu aviso de que o locador não pretende renovar o contrato e já negocia o imóvel com uma grande rede concorrente.","avatarBg":"bg-orange-950 text-orange-200 border-orange-500"},"briefing":{"mentorName":"Dr. Roberto Ramos","mentorQuote":"Empresarial também é prazo. Antes de discutir justiça, descubra se o cliente ainda possui a ferramenta processual adequada.","facts":["A cafeteria ocupa o ponto há mais de cinco anos.","Houve contratos escritos sucessivos.","O prazo para medida renovatória está no limite.","A marca depende fortemente da localização atual."],"mainObjective":"Verificar requisitos e tempestividade para proteção do ponto empresarial e impedir perda estratégica do estabelecimento.","legalContext":"Locação não residencial, ação renovatória, fundo de comércio, prova contratual e prazos materiais/processuais."},"locations":[{"id":"C09_ESCRITORIO","name":"Ramos & Associados — Empresarial","category":"escritorio","travelTimeHours":0,"travelCost":0,"description":"Mesa de contratos com calendário crítico.","address":"Av. Paulista, 1200","iconName":"Building2","color":"text-amber-500","unlockedByDefault":true,"characters":[{"id":"C09_ROBERTO","name":"Dr. Roberto Ramos","role":"Sócio","avatarIcon":"Briefcase","avatarBg":"bg-slate-800 text-amber-300 border-amber-500","initialDialogue":"Conte prazo antes de contar história.","dialogueOptions":[{"id":"C09_D_PRAZO","question":"Por que o prazo é o primeiro ponto?","answer":"Porque um direito comercial forte pode ser perdido se a ação própria não for ajuizada na janela legal.","timeCostMinutes":10}]}],"searchables":[{"id":"C09_S_CONTRATOS","name":"Sequência de contratos","description":"Somar períodos escritos e verificar continuidade.","timeCostMinutes":40,"foundClueId":"C09_CLUE_CONTRATOS","inspectedMessage":"Os instrumentos demonstram ocupação escrita e contínua superior a cinco anos."}]},{"id":"C09_CAFE","name":"Café Horizonte","category":"empresa","travelTimeHours":1,"travelCost":18,"description":"Loja movimentada em esquina comercial consolidada.","address":"Jardins - São Paulo","iconName":"Building","color":"text-orange-400","unlockedByDefault":true,"characters":[{"id":"C09_SOCIA","name":"Fernanda Melo","role":"Sócia Administradora","avatarIcon":"User","avatarBg":"bg-orange-950 text-orange-200 border-orange-500","initialDialogue":"Sem esse ponto, perdemos boa parte do movimento.","dialogueOptions":[{"id":"C09_D_ATIVIDADE","question":"A atividade permaneceu a mesma?","answer":"Sim. Funcionamos como cafeteria e confeitaria desde a inauguração.","revealsClueId":"C09_CLUE_MESMO_RAMO","timeCostMinutes":15},{"id":"C09_D_AVISO","question":"Quando o aviso do locador chegou?","answer":"Recebemos há quatro dias. Trouxe o envelope e o e-mail.","revealsClueId":"C09_CLUE_NOTIFICACAO","timeCostMinutes":15}]}],"searchables":[{"id":"C09_S_FATURAMENTO","name":"Histórico operacional","description":"Demonstrar estabelecimento e clientela.","timeCostMinutes":30,"foundClueId":"C09_CLUE_FUNDO_COMERCIO","inspectedMessage":"Relatórios mostram operação contínua, equipe fixa e clientela recorrente no endereço."}]},{"id":"C09_CARTORIO","name":"Registro de Imóveis","category":"cartorio","travelTimeHours":2,"travelCost":30,"description":"Cartório responsável pela matrícula do imóvel.","address":"Cerqueira César - São Paulo","iconName":"ScrollText","color":"text-purple-400","unlockedByDefault":true,"characters":[],"searchables":[{"id":"C09_S_MATRICULA","name":"Matrícula do ponto comercial","description":"Confirmar proprietário e eventuais ônus.","timeCostMinutes":30,"foundClueId":"C09_CLUE_PROPRIETARIO","inspectedMessage":"A matrícula confirma legitimidade do locador e ausência de alienação já registrada."}]}],"availableClues":[{"id":"C09_CLUE_CONTRATOS","title":"Contratos escritos sucessivos","type":"documento","relevance":"crucial","isAuthentic":true,"summary":