    '{"client":{"name":"Maurício Leal","occupation":"Empresário aposentado, 61 anos","summary":"Maurício teve contas bloqueadas em execução fiscal de uma empresa da qual saiu anos antes do período em que a dívida tributária foi constituída.","avatarBg":"bg-sky-950 text-sky-200 border-sky-500"},"briefing":{"mentorName":"Dr. Otávio Brandão","mentorQuote":"Execução fiscal cobra precisão documental. Uma data societária pode valer mais que dez páginas de indignação.","facts":["Maurício vendeu suas quotas e saiu formalmente da administração.","A dívida refere-se a períodos posteriores.","O bloqueio atingiu conta usada para despesas familiares.","A Fazenda sustenta responsabilidade de ex-administrador."],"mainObjective":"Demonstrar a cronologia societária e afastar redirecionamento indevido da execução.","legalContext":"Responsabilidade tributária de sócios e administradores, execução fiscal, redirecionamento e prova registral."},"locations":[{"id":"C11_ESCRITORIO","name":"Núcleo Tributário","category":"escritorio","travelTimeHours":0,"travelCost":0,"description":"Sala de execuções fiscais e pesquisa cadastral.","address":"Av. Paulista, 1200","iconName":"FolderCheck","color":"text-sky-400","unlockedByDefault":true,"characters":[{"id":"C11_OTAVIO","name":"Dr. Otávio Brandão","role":"Tributarista","avatarIcon":"Briefcase","avatarBg":"bg-slate-800 text-sky-300 border-sky-500","initialDialogue":"Faça uma linha do tempo societária.","dialogueOptions":[{"id":"C11_D_REDIREC","question":"Ser sócio no passado basta para responder?","answer":"Não. Precisamos identificar período, função, ato imputado e fundamento jurídico do redirecionamento.","timeCostMinutes":15}]}],"searchables":[{"id":"C11_S_CDA","name":"Certidão de Dívida Ativa e decisão de redirecionamento","description":"Comparar períodos e fundamento.","timeCostMinutes":40,"foundClueId":"C11_CLUE_PERIODO","inspectedMessage":"Os fatos geradores são de 2024 e 2025; Maurício saiu da empresa em 2021."}]},{"id":"C11_JUNTA","name":