ativo atende desempenho e segurança.","fullDetail":"Laboratório acreditado comprova equivalência por critérios objetivos.","locationFoundId":"C12_CLIENTE","legalSignificance":"Mostra que restrição proprietária não é necessária para o interesse público.","iconName":"FolderCheck"}],"strategies":[{"id":"C12_STRAT_OTIMA","title":"Impugnação e controle de legalidade com prova de equivalência","branch":"Administrativo","description":"Pedir correção/suspensão da cláusula restritiva antes da sessão.","isOptimal":true,"scoreWeight":100,"requiredCrucialClueIds":["C12_CLUE_SEM_JUSTIFICATIVA","C12_CLUE_COPIA_ANTERIOR","C12_CLUE_EQUIVALENCIA"],"rationale":"Demonstra falta de motivação e existência de solução equivalente."},{"id":"C12_STRAT_MEDIA","title":"Participar mesmo sem cumprir e recorrer depois","branch":"Administrativo","description":"Esperar a desclassificação.","isOptimal":false,"scoreWeight":42,"requiredCrucialClueIds":[],"rationale":"Desperdiça a janela preventiva e aumenta risco."},{"id":"C12_STRAT_ERRADA","title":"Acusar corrupção sem prova","branch":"Penal","description":"Afirmar pagamento de vantagem sem qualquer elemento.","isOptimal":false,"scoreWeight":15,"requiredCrucialClueIds":[],"rationale":"Confunde restrição ilegal com crime não demonstrado."}],"minimumPassingScore":80}'::jsonb,
